window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e0c77718c6f2f7a5"]={"versions": [{"id": "FIG-e0c77718c6f2f7a5", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Übersichtsschaubild zur Klassifikation und Abgrenzung der AUTOSAR-Template-Spezifikationen (TPS) innerhalb des AUTOSAR Data Exchange Formats. Das Diagramm gliedert die Spezifikationsdokumente horizontal in zwei Schichten: inhaltlich-semantische Datenstrukturen (Content and Semantics) oben und physikalische XML-Repräsentations- bzw. Formatvorgaben (Physical Representation and XML Data Format) unten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält zwei übergeordnete Schicht-Container und acht untergeordnete Dokument-Entitäten in Form abgerundeter Rechtecke:</p>\n<ol class=\"fig-list\">\n<li>Oberer Schicht-Container: „Content and Semantics (AUTOSAR Specific Data Structure and Semantics)“</li>\n</ol>\n<ul class=\"fig-list\">\n<li>„AUTOSAR TPS SoftwareComponentTemplate“</li>\n<li>„AUTOSAR TPS SystemTemplate“</li>\n<li>„AUTOSAR TPS ECUConfigurationTemplate“</li>\n<li>„AUTOSAR TPS GenericStructureTemplate“</li>\n<li>„AUTOSAR TPS StandardizationTemplate“</li>\n<li>„AUTOSAR TPS <other>“ (Platzhalter für weitere semantische Templates)</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Unterer Schicht-Container: „Physical Representation and XML Data Format (General File System and XML Processing)“</li>\n</ol>\n<ul class=\"fig-list\">\n<li>„AUTOSAR TPS ARXMLSerializationRules“</li>\n<li>„AUTOSAR TPS XMLSchemaProductionRules“</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen oder gerichtete Beziehungen zwischen den einzelnen Blöcken sind im Diagramm nicht explizit modelliert; die Kopplung erfolgt implizit über die Schichtenzuordnung.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Klassifikationsdiagramm ohne dynamische Abläufe, Sequenzen, Trigger oder Nachrichtenaustausche. Es visualisiert die funktionale Domänenteilung bei der Verarbeitung und Modellierung von AUTOSAR-XML-Artefakten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die methodische Trennung von Datenmodell und XML-Serialisierung: Während Templates der oberen Schicht fachliche Metamodelle und Semantiken definieren, verpflichten die Dokumente der unteren Schicht Tool-Hersteller auf standardisierte XML-Schema-Erzeugung (<code>XMLSchemaProductionRules</code>) sowie deterministische Serialisierungsregeln (<code>ARXMLSerializationRules</code>, z. B. Zeichenkodierung, Einrückung, Fragmentierung und Namensraum-Präfixe) zur Sicherstellung verlustfreier Tool-Interoperabilität.</p>"}, {"id": "FIG-4cc01625c61b6de8", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Übersichtsschaubild zur Klassifikation und Abgrenzung der AUTOSAR-Template-Spezifikationen (TPS) innerhalb des AUTOSAR Data Exchange Formats. Das Diagramm gliedert die Spezifikationsdokumente horizontal in zwei Schichten: inhaltlich-semantische Datenstrukturen (Content and Semantics) oben und physikalische XML-Repräsentations- bzw. Formatvorgaben (Physical Representation and XML Data Format) unten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält zwei übergeordnete Schicht-Container und acht untergeordnete Dokument-Entitäten in Form abgerundeter Rechtecke:</p>\n<ol class=\"fig-list\">\n<li>Oberer Schicht-Container: „Content and Semantics (AUTOSAR Specific Data Structure and Semantics)“</li>\n</ol>\n<ul class=\"fig-list\">\n<li>„AUTOSAR TPS SoftwareComponentTemplate“</li>\n<li>„AUTOSAR TPS SystemTemplate“</li>\n<li>„AUTOSAR TPS ECUConfigurationTemplate“</li>\n<li>„AUTOSAR TPS GenericStructureTemplate“</li>\n<li>„AUTOSAR TPS StandardizationTemplate“</li>\n<li>„AUTOSAR TPS <other>“ (Platzhalter für weitere semantische Templates)</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Unterer Schicht-Container: „Physical Representation and XML Data Format (General File System and XML Processing)“</li>\n</ol>\n<ul class=\"fig-list\">\n<li>„AUTOSAR TPS ARXMLSerializationRules“</li>\n<li>„AUTOSAR TPS XMLSchemaProductionRules“</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen oder gerichtete Beziehungen zwischen den einzelnen Blöcken sind im Diagramm nicht explizit modelliert; die Kopplung erfolgt implizit über die Schichtenzuordnung.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Klassifikationsdiagramm ohne dynamische Abläufe, Sequenzen, Trigger oder Nachrichtenaustausche. Es visualisiert die funktionale Domänenteilung bei der Verarbeitung und Modellierung von AUTOSAR-XML-Artefakten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die methodische Trennung von Datenmodell und XML-Serialisierung: Während Templates der oberen Schicht fachliche Metamodelle und Semantiken definieren, verpflichten die Dokumente der unteren Schicht Tool-Hersteller auf standardisierte XML-Schema-Erzeugung (<code>XMLSchemaProductionRules</code>) sowie deterministische Serialisierungsregeln (<code>ARXMLSerializationRules</code>, z. B. Zeichenkodierung, Einrückung, Fragmentierung und Namensraum-Präfixe) zur Sicherstellung verlustfreier Tool-Interoperabilität.</p>"}], "trans": [{"from": "FIG-e0c77718c6f2f7a5", "to": "FIG-4cc01625c61b6de8", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
